rc_progress': ['authority-output:aa4dadf8-e409-4921-a42c-0ceef850f0b7:story_planning.candidate:v1'], 'focalization': 'INTERNAL', 'participants': ['character:character:shen-yan', 'character:character:tang-sui', 'character:character:lu-heng'], 'reader_effect': '以采下的叶片和留下的芽根兑现现场判断。', 'scene_version': 1, 'scene_group_id': 'chapter:5:group:harvest', 'obligation_refs': [], 'trajectory_refs': [], 'world_event_ids': [], 'information_gain': ['chapter:5:fact:handwork'], 'pov_character_id': 'character:character:shen-yan', 'state_transitions': [], 'accessible_knowledge': ['local:publishHarvestRule', 'chapter:5:fact:route', 'chapter:5:fact:mature-share'], 'realization_event_ids': ['group-4:e3'], 'narrative_time_relation': 'ADVANCES', 'realization_capabilities': ['ACTION', 'DIALOGUE', 'DESCRIPTION', 'INTERIOR', 'TRANSITION']}, {'goal': '交回采收物，弄清实际质量与下一次要改的处理动作。', 'beats': [{'beat_id': 'chapter:5:scene:4:beat:1', 'ordinal': 1, 'function': '三人交回叶片；唐穗翻看分装层次与叶面，指出干净、未被重物压坏的部分。', 'expected_reader_effect': '感到一路保存的用心得到实物证明。'}, {'beat_id': 'chapter:5:scene:4:beat:2', 'ordinal': 2, 'function': '检查发现一小部分叶柄处理较粗，沈砚承认采时急促并说出下次要放慢、托稳的动作；程观记录各人的实际工作，额度待另行核验。', 'expected_reader_effect': '喜悦中留下一处可信的学习缺口。'}], 'conflict': '沈砚期待整篓都好；实物检查显示分装保存得当，却暴露一处采后处理差别。', 'scene_id': 'chapter:5:scene:delivery', 'exit_state': '首次采收物已交回药房并获得依据说明与实物的质量反馈；一处保存得当、一处处理待改，各人贡献可追溯，劳动额度与正式课程条件仍未核定。', 'story_time': {'precision': 'ORDERED', 'end_ordinal': 4, 'timeline_id': 'chapter:5', 'start_ordinal': 4}, 'entry_state': '三人按现场份额采得成熟外叶，中心芽和根留在原处；叶片已分装背出山谷，尚待药房实物检查。', 'location_id': 'unit:herb-store', 'arc_progress': ['authority-output:aa4dadf8-e409-4921-a42c-0ceef850f0b7:story_planning.candidate:v1', 'authority-output:6981b0a9-d992-4788-b8e1-5d1c2bdc887d:story_planning.candidate:v1'], 'focalization': 'INTERNAL', 'participants': ['character:character:shen-yan', 'character:character:tang-sui', 'character:character:lu-heng', 'character:character:cheng-guan'], 'reader_effect': '得到有依据的首次交付结果，并看见反馈怎样变成下一次实践的具体办法。', 'scene_vers